const POLL_SECONDS = 2;
const TICK_MILLISECONDS = POLL_SECONDS * 1000;

interface GateArgs {
  readonly input: number;
}

/** The status a rate-limited request fails with (Too Many Requests). */
const RATE_LIMITED_STATUS = 429;

/**
 * A read handle whose every request answers at once with its own ordinal (1, 2, ...), unless
 * it is told to refuse the next one: that request fails rate-limited, carrying *retryAfterMs*.
 * A refused load drops the value shown; a refused refresh keeps it.
 */
class OrdinalHandle {
  readonly isLoaded = signal(false);
  readonly isLoading = signal(false);
  readonly error = signal<ProblemDetails | null>(null);
  readonly answered = signal<number | null>(null);
  requests = 0;
  /** How many requests the server answered (a refused one is not answered). */
  answers = 0;
  private refuseNext = false;

  constructor(private readonly retryAfterMs: number | null) {}

  refuse(): void {
    if (this.refuseNext) {
      throw new Error("The next request is already refused; a row repeats 'limit'.");
    }
    this.refuseNext = true;
  }

  load(_args: GateArgs): void {
    this.settle(true);
  }

  refresh(): Promise<void> {
    this.settle(false);
    return Promise.resolve();
  }

  private settle(load: boolean): void {
    this.requests += 1;
    if (this.refuseNext) {
      this.refuseNext = false;
      if (load) {
        this.answered.set(null);
        this.isLoaded.set(false);
      }
      this.error.set({
        type: 'about:blank',
        title: 'Too Many Requests',
        detail: '',
        status: RATE_LIMITED_STATUS,
        errors: [],
        retryAfterMs: this.retryAfterMs,
      });
      return;
    }
    this.answers += 1;
    this.answered.set(this.requests);
    this.isLoaded.set(true);
    this.error.set(null);
  }
}

